import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- CUDA / C++ source ----------
src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef EPS
#define EPS 1e-5f
#endif

// -----------------------------------------------------------------------------
// 1) Compute per‑group sum and sum‑of‑squares
// -----------------------------------------------------------------------------
template <typename scalar_t>
__global__ void groupnorm_sum_kernel(
    const scalar_t* __restrict__ input,
    float* __restrict__ sum,
    float* __restrict__ sumsq,
    const int N,
    const int C,
    const int H,
    const int W,
    const int G,
    const int channels_per_group)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * H * W;
    if (idx >= total) return;

    // unravel idx -> (n, c, h, w)
    int w = idx % W;
    int h = (idx / W) % H;
    int c = (idx / (W * H)) % C;
    int n = idx / (C * H * W);

    int g = c / channels_per_group;          // group index within sample
    int group_idx = n * G + g;               // flattened (sample, group)

    float val = static_cast<float>(input[idx]);
    atomicAdd(&sum[group_idx],     val);
    atomicAdd(&sumsq[group_idx],   val * val);
}

// -----------------------------------------------------------------------------
// 2) Derive mean and variance from the sums
// -----------------------------------------------------------------------------
__global__ void compute_mean_var_kernel(
    const float* __restrict__ sum,
    const float* __restrict__ sumsq,
    float* __restrict__ mean,
    float* __restrict__ var,
    const int groups_total,
    const int group_size)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= groups_total) return;

    float s  = sum[idx];
    float ss = sumsq[idx];
    float m  = s  / static_cast<float>(group_size);
    float v  = ss / static_cast<float>(group_size) - m * m;
    mean[idx] = m;
    var[idx]  = v;
}

// -----------------------------------------------------------------------------
// 3) Normalise each element using the per‑group statistics and affine params
// -----------------------------------------------------------------------------
template <typename scalar_t>
__global__ void groupnorm_norm_kernel(
    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    const int N,
    const int C,
    const int H,
    const int W,
    const int G,
    const int channels_per_group)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * H * W;
    if (idx >= total) return;

    // unravel idx -> (n, c, h, w)
    int w = idx % W;
    int h = (idx / W) % H;
    int c = (idx / (W * H)) % C;
    int n = idx / (C * H * W);

    int g = c / channels_per_group;
    int group_idx = n * G + g;

    float mu   = mean[group_idx];
    float sigma = sqrtf(var[group_idx] + EPS);
    float x    = static_cast<float>(input[idx]);

    float norm = (x - mu) / sigma;

    float wgt = static_cast<float>(weight[c]);
    float b   = static_cast<float>(bias[c]);

    float y = norm * wgt + b;
    output[idx] = static_cast<scalar_t>(y);
}

// -----------------------------------------------------------------------------
// Public entry point
// -----------------------------------------------------------------------------
std::vector<torch::Tensor> groupnorm_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    const int64_t num_groups)
{
    const int N = input.size(0);
    const int C = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);
    const int G = static_cast<int>(num_groups);
    const int channels_per_group = C / G;
    const int group_size = channels_per_group * H * W;
    const int groups_total = N * G;

    // Allocate temporary buffers
    auto sum   = torch::zeros({N, G}, input.options().dtype(torch::kFloat));
    auto sumsq = torch::zeros({N, G}, input.options().dtype(torch::kFloat));
    auto mean  = torch::empty({N, G}, input.options().dtype(torch::kFloat));
    auto var   = torch::empty({N, G}, input.options().dtype(torch::kFloat));
    auto output = torch::empty_like(input);

    const int threads = 256;
    const int total_elems = N * C * H * W;
    const int blocks = (total_elems + threads - 1) / threads;

    // 1) Sum & sum‑of‑squares
    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "groupnorm_sum_kernel", ([&] {
        groupnorm_sum_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            sum.data_ptr<float>(),
            sumsq.data_ptr<float>(),
            N, C, H, W, G, channels_per_group);
    }));

    // 2) Mean & variance
    const int blocks_g = (groups_total + threads - 1) / threads;
    compute_mean_var_kernel<<<blocks_g, threads>>>(
        sum.data_ptr<float>(),
        sumsq.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        groups_total,
        group_size);

    // 3) Normalise + affine
    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "groupnorm_norm_kernel", ([&] {
        groupnorm_norm_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            mean.data_ptr<float>(),
            var.data_ptr<float>(),
            weight.data_ptr<scalar_t>(),
            bias.data_ptr<scalar_t>(),
            N, C, H, W, G, channels_per_group);
    }));

    return {output};
}
'''  # end of src string

# Compile the extension
ext = load_inline(name='groupnorm_ext',
                  cpp_sources='',
                  cuda_sources=src,
                  functions=['groupnorm_forward'],
                  verbose=False)

# ---------- Python wrapper ----------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for nn.GroupNorm using a custom CUDA kernel.
    All tensors are fp16 (torch.float16). Accumulation is performed in fp32.
    """
    def __init__(self, num_features: int, num_groups: int, eps: float = 1e-5, affine: bool = True):
        super().__init__()
        self.num_features = num_features
        self.num_groups = num_groups
        self.eps = eps
        self.affine = affine

        if self.affine:
            self.weight = nn.Parameter(torch.ones(num_features, dtype=torch.float16))
            self.bias   = nn.Parameter(torch.zeros(num_features, dtype=torch.float16))
        else:
            self.register_parameter('weight', None)
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Input: (N, C, H, W) fp16 tensor.
        Output: same shape, fp16, normalized per group.
        """
        if x.dtype != torch.float16:
            raise TypeError("ModelNew expects fp16 inputs")
        if x.dim() != 4:
            raise ValueError("ModelNew only supports 4‑D tensors (N, C, H, W)")

        weight = self.weight if self.affine else torch.ones(self.num_features,
                                                             dtype=torch.float16,
                                                             device=x.device)
        bias   = self.bias   if self.affine else torch.zeros(self.num_features,
                                                             dtype=torch.float16,
                                                             device=x.device)

        out = ext.groupnorm_forward(x, weight, bias, self.num_groups)[0]
        return out

# ---------- Helper functions matching the reference ----------
def get_inputs():
    batch_size = 112
    features = 64
    dim1 = 512
    dim2 = 512
    x = torch.rand(batch_size, features, dim1, dim2, dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    features = 64
    num_groups = 8
    return [features, num_groups]

# Example sanity check (can be removed in production)
if __name__ == "__main__":
    torch.manual_seed(0)
    x = get_inputs()[0]
    model_ref = nn.GroupNorm(num_groups=8, num_channels=64).cuda().half()
    model_new = ModelNew(num_features=64, num_groups=8).cuda().half()
    # copy parameters for fair comparison
    with torch.no_grad():
        model_new.weight.copy_(model_ref.weight)
        model_new.bias.copy_(model_ref.bias)

    y_ref = model_ref(x)
    y_new = model_new(x)
    print("max diff:", (y_ref - y_new).abs().max().item())
